import XCTest
import CoreGraphics
@testable import Stack_to_Six
@MainActor final class NativeSourceTutorialFreePlayPlanTests:XCTestCase {
 func testSpecialTargetCycleCoversEveryLiveDieBeforeRepeatingAndDropsRemovedTargets() {
  var cycle=NativeTutorialTargetCycle()
  XCTAssertEqual(cycle.select(["top","middle","bottom"]),"top")
  XCTAssertEqual(cycle.select(["top","middle","bottom"]),"middle")
  XCTAssertEqual(cycle.select(["middle","top","bottom"]),"bottom")
  XCTAssertEqual(cycle.select(["bottom","top","middle"]),"top")
  XCTAssertEqual(cycle.select(["bottom","top"]),"bottom")
  XCTAssertEqual(cycle.select(["top"]),"top")
  XCTAssertNil(cycle.select([]))
  XCTAssertEqual(cycle.select(["new"]),"new")
 }
 struct Rect:Decodable {let left:Double,top:Double,width:Double,height:Double;var cg:CGRect{CGRect(x:left,y:top,width:width,height:height)}}
 struct Candidate:Decodable{let id:String,column:Int,row:Int,rect:Rect}
 struct Move:Decodable{let from:Rect,to:Rect}
 struct Sample:Decodable{let time:Double,x:Double,y:Double,alpha:Double,scale:Double,rotation:Double}
 struct Case:Decodable{let candidates:[Candidate],moves:[Move],seed:Int,draws:Int,duration:Double,cycle:Double,samples:[Sample]}
 func testOriginal24CasesPreserveShuffleDrawOrderAndActualGSAPChannels()throws {
  let cases=try JSONDecoder().decode([Case].self,from:Data(Self.original.utf8))
  for original in cases {
   var draws=0
   let candidates=original.candidates.map{NativeSourceTutorialFreePlayPlan.Candidate(id:$0.id,column:$0.column,row:$0.row,rect:$0.rect.cg)}
   let plan=try XCTUnwrap(NativeSourceTutorialFreePlayPlan.make(candidates:candidates,columns:5,rows:9,random:{draws+=1;return Double((draws*37+original.seed*11)%97)/97},cellRect:{c,r in CGRect(x:24+c*70,y:100+r*70,width:60,height:60)},current:{true}))
   XCTAssertEqual(draws,original.draws);XCTAssertEqual(plan.moves,original.moves.map{.init(from:$0.from.cg,to:$0.to.cg)})
   XCTAssertEqual(plan.duration,original.duration,accuracy:1e-8);XCTAssertEqual(plan.cycle,original.cycle,accuracy:1e-8)
   // The actual Source timeline family emits no onUpdate at local0.
   // An unrendered paused oracle at0 still contains the input shell origin.
   for sample in original.samples where sample.time>0 {
    let pose=try XCTUnwrap(plan.pose(seconds:sample.time,fingertip:CGPoint(x:18,y:24)))
    XCTAssertEqual(pose.position.x,sample.x,accuracy:2e-5,"seed \(original.seed), time \(sample.time)")
    XCTAssertEqual(pose.position.y,sample.y,accuracy:2e-5)
    XCTAssertEqual(pose.alpha,sample.alpha,accuracy:2e-6);XCTAssertEqual(pose.scale,sample.scale,accuracy:2e-6);XCTAssertEqual(pose.rotation,sample.rotation,accuracy:2e-6)
   }
  }
 }
 func testRetirementDuringMathCannotConsumeRemainingDirections() {
  var active=true,draws=0
  XCTAssertNil(NativeSourceTutorialFreePlayPlan.make(candidates:[],columns:5,rows:9,random:{draws+=1;active=false;return 0.5},cellRect:{_,_ in XCTFail("retired cell rect");return nil},current:{active}))
  XCTAssertEqual(draws,1)
 }
